section.sourcecode:
module yang-tmf-map {
  yang-version "1.1";
  ...
  extension cfs-service {
    argument "name";
    description
      "The TMF CFS Service that this YANG subtree maps to.";
  }
  extension rfs-service {
    argument "name";
    description
      "The TMF RFS Resource that this YANG subtree maps to."; 
  }
  extension resource {
    argument "name";
    description
      "The TMF Resource that this YANG subtree maps to.";
  }
  extension ignore {
    description
      "Indicates that the annotated YANG data node and its
      subtree are ignored by the mapping mechanism.";
  }
}

module netinfra {
  yang-version "1.1";
  ...
  import yang-tmf-map {
    prefix tmf;
  }

  container netinfra {
    description "Network infrastructure";
    list router {
      description "Network Infrastructure Router";
      key name;

      orchestron:transform sorespo.cfs.Router;
      tmf:cfs-service "Router";

      leaf name {
        type string;
        description "Router name";
      }
      leaf id {
        type uint32;
        description "Router ID";
        mandatory true;
      }
    }
  }
}
